import React, { useRef } from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";
import "./MiniSlider.css"

// Right arrow button
function ButtonRight(props) {
  const { className, onClick } = props;
  return (
    <div className={`${className} btn`} onClick={onClick}>
      <img src="/icons/button-right1.png" alt="Next" />
    </div>
  );
}

// Left arrow button
function ButtonLeft(props) {
  const { className, onClick } = props;
  return (
    <div className={`${className} btn`} onClick={onClick}>
      <img src="/icons/button-left1.png" alt="Previous" />
    </div>
  );
}

// Slider component
function MiniSlider() {
  const sliderRef = useRef(null);

  // Autoplay methods (play/pause)
  const play = () => {
    if (sliderRef.current) sliderRef.current.slickPlay();
  };

  const pause = () => {
    if (sliderRef.current) sliderRef.current.slickPause();
  };

  const settings = {
    dots: false,
    infinite: true,
    speed: 500,
    slidesToShow: 6, // Number of slides to show at a time
    slidesToScroll: 1, // Number of slides to scroll per swipe
    autoplay: true,
    autoplaySpeed: 4000,
    nextArrow: <ButtonRight />, // Custom next arrow button
    prevArrow: <ButtonLeft />, // Custom prev arrow button
  };

  return (
    <div className="container">
      {/* Slider component with ref */}
      <Slider {...settings} ref={sliderRef}>
        <div>
          <img src="/brand_logos/1.webp" alt="Brand 1" />
        </div>
        <div>
          <img src="/brand_logos/2.webp" alt="Brand 2" />
        </div>
        <div>
          <img src="/brand_logos/3.webp" alt="Brand 3" />
        </div>
        <div>
          <img src="/brand_logos/8.webp" alt="Brand 8" />
        </div>
        <div>
          <img src="/brand_logos/9.webp" alt="Brand 9" />
        </div>
        <div>
          <img src="/brand_logos/15.webp" alt="Brand 15" />
        </div>
        <div>
          <img src="/brand_logos/16.webp" alt="Brand 16" />
        </div>
        <div>
          <img src="/brand_logos/17.webp" alt="Brand 17" />
        </div>
        <div>
          <img src="/brand_logos/18.webp" alt="Brand 18" />
        </div>
        <div>
          <img src="/brand_logos/19.webp" alt="Brand 19" />
        </div>
        <div>
          <img src="/brand_logos/20.webp" alt="Brand 20" />
        </div>
        <div>
          <img src="/brand_logos/21.webp" alt="Brand 21" />
        </div>
      </Slider>

      {/* Autoplay controls */}
      <div className="controls">
        <button onClick={play}>Play</button>
        <button onClick={pause}>Pause</button>
      </div>
    </div>
  );
}

export default MiniSlider;
